class Solution {
public:
    bool isRobotBounded(string instructions) {
        int x = 0, y = 0;
        int dx = 0, dy = 1;
        for (char inst : instructions) {
            if (inst == 'G') {
                x += dx;
                y += dy;
            } else if (inst == 'L') {
                int temp = dx;
                dx = -dy;
                dy = temp;
            } else if (inst == 'R') {
                int temp = dx;
                dx = dy;
                dy = -temp;
            }
        }
        return (x == 0 && y == 0) || !(dx == 0 && dy == 1);
    }
};

class Solution {
    public boolean isRobotBounded(String instructions) {
        int x = 0, y = 0;
        int dx = 0, dy = 1;
        for (int i = 0; i < instructions.length(); ++i) {
            char inst = instructions.charAt(i);
            if (inst == 'G') {
                x += dx;
                y += dy;
            } else if (inst == 'L') {
                int temp = dx;
                dx = -dy;
                dy = temp;
            } else if (inst == 'R') {
                int temp = dx;
                dx = dy;
                dy = -temp;
            }
        }
        return (x == 0 && y == 0) || !(dx == 0 && dy == 1);
    }
}

var isRobotBounded = function(instructions) {
    let x = 0, y = 0;
    let dx = 0, dy = 1;
    for (const inst of instructions) {
        if (inst === 'G') {
            x += dx;
            y += dy;
        } else if (inst === 'L') {
            const temp = dx;
            dx = -dy;
            dy = temp;
        } else if (inst === 'R') {
            const temp = dx;
            dx = dy;
            dy = -temp;
        }
    }
    return (x === 0 && y === 0) || !(dx === 0 && dy === 1);
};
